export type DagSpec = {
    /**
     * Spec Version
     */
    spec_version?: 2;
    /**
     * Dag Id
     */
    dag_id: string;
    /**
     * Output Mode
     */
    output_mode?: 'python' | 'loader' | 'yaml';
    /**
     * Display Name
     */
    display_name?: string | null;
    /**
     * Description
     */
    description?: string | null;
    /**
     * Doc Md
     */
    doc_md?: string | null;
    /**
     * Schedule
     */
    schedule?: ({
        type: 'none';
    } & NoSchedule) | ({
        type: 'preset';
    } & PresetSchedule) | ({
        type: 'cron';
    } & CronSchedule) | ({
        type: 'interval';
    } & IntervalSchedule) | ({
        type: 'multi_cron';
    } & MultiCronSchedule) | ({
        type: 'events';
    } & EventsSchedule) | ({
        type: 'assets';
    } & AssetSchedule) | ({
        type: 'assets_or_time';
    } & AssetOrTimeScheduleSpec) | ({
        type: 'assets_and_time';
    } & AssetAndTimeScheduleSpec) | ({
        type: 'partitioned_cron';
    } & PartitionedCronSchedule) | ({
        type: 'partitioned_assets';
    } & PartitionedAssetSchedule);
    /**
     * Timezone
     *
     * DAG timezone (IANA). start/end dates are wall-clock times in it and schedules without their own timezone (presets, cron, intervals) follow it. None: Airflow's default_timezone (UTC unless configured).
     */
    timezone?: string | null;
    /**
     * Start Date
     */
    start_date?: string | null;
    /**
     * End Date
     */
    end_date?: string | null;
    /**
     * Catchup
     */
    catchup?: boolean;
    /**
     * Tags
     */
    tags?: Array<string>;
    /**
     * Max Active Runs
     */
    max_active_runs?: number | null;
    /**
     * Max Active Tasks
     */
    max_active_tasks?: number | null;
    /**
     * Dagrun Timeout Seconds
     */
    dagrun_timeout_seconds?: number | null;
    /**
     * Is Paused Upon Creation
     */
    is_paused_upon_creation?: boolean | null;
    default_args?: DefaultArgs;
    /**
     * Params
     */
    params?: {
        [key: string]: unknown | DagParam;
    };
    /**
     * DAG-level on_success / on_failure only.
     */
    callbacks?: Callbacks;
    /**
     * Deadlines
     */
    deadlines?: Array<DeadlineSpec>;
    /**
     * Fail Fast
     */
    fail_fast?: boolean | null;
    /**
     * Max Consecutive Failed Dag Runs
     */
    max_consecutive_failed_dag_runs?: number | null;
    /**
     * Owner Links
     */
    owner_links?: {
        [key: string]: string;
    };
    /**
     * Render Template As Native Obj
     */
    render_template_as_native_obj?: boolean | null;
    /**
     * Rerun With Latest Version
     */
    rerun_with_latest_version?: boolean | null;
    /**
     * Team
     */
    team?: string | null;
    /**
     * Lineage
     *
     * OpenLineage for the whole DAG (selective enable/disable).
     */
    lineage?: 'inherit' | 'enabled' | 'disabled';
    /**
     * Environments
     */
    environments?: {
        [key: string]: unknown | EnvironmentOverlay;
    };
    /**
     * Nodes
     */
    nodes?: Array<OperatorNode | PythonTaskNode | TaskGroupNode | CustomNode | NoteNode>;
    /**
     * Edges
     */
    edges?: Array<Edge>;
    /**
     * Raw Code
     *
     * Raw code DAG: the complete DAG file, written by hand and deployed as it is (no generated code, no spec rules; validated by syntax, lint, secret, policy and import checks). Set: nodes and edges must be empty, output_mode is python and environment overlays do not change the file. Absent: a spec-backed (visual) DAG.
     */
    raw_code?: string | null;
};

