/**
 * PythonTaskNode
 *
 * A TaskFlow task whose body is user-supplied Python (privileged).
 *
 * ``decorator`` selects ``@task``, ``@task.branch`` (return the downstream task id(s)
 * to follow), ``@task.short_circuit`` (return falsy to skip downstream),
 * ``@task.virtualenv``, ``@task.sensor`` (return bool / PokeReturnValue),
 * ``@task.bash`` (return a command) and friends; ``decorator_kwargs`` are passed to it.
 */
export type PythonTaskNode = {
    /**
     * Id
     */
    id: string;
    /**
     * Label
     *
     * Canvas label only.
     */
    label?: string | null;
    /**
     * Icon
     *
     * Canvas icon only (builtin:<logo> or custom:<name>); overrides the default.
     */
    icon?: string | null;
    /**
     * Parent Group
     *
     * Id of a task_group node.
     */
    parent_group?: string | null;
    position?: Position;
    /**
     * Task Id
     */
    task_id: string;
    /**
     * Trigger Rule
     */
    trigger_rule?: 'all_success' | 'all_failed' | 'all_done' | 'all_done_min_one_success' | 'all_skipped' | 'one_success' | 'one_done' | 'one_failed' | 'none_failed' | 'none_failed_min_one_success' | 'none_skipped' | 'always' | 'all_done_setup_success' | null;
    /**
     * Retries
     */
    retries?: number | null;
    /**
     * Retry Delay Seconds
     */
    retry_delay_seconds?: number | null;
    /**
     * Execution Timeout Seconds
     */
    execution_timeout_seconds?: number | null;
    /**
     * Pool
     */
    pool?: string | null;
    /**
     * Pool Slots
     */
    pool_slots?: number | null;
    /**
     * Queue
     */
    queue?: string | null;
    /**
     * Owner
     */
    owner?: string | null;
    /**
     * Doc Md
     */
    doc_md?: string | null;
    /**
     * Outlets
     */
    outlets?: Array<AssetRef>;
    /**
     * Inlets
     */
    inlets?: Array<AssetRef>;
    mapping?: MappingSpec | null;
    /**
     * Is Setup
     */
    is_setup?: boolean;
    /**
     * Is Teardown
     */
    is_teardown?: boolean;
    callbacks?: Callbacks;
    retry_policy?: RetryPolicySpec | null;
    /**
     * Retry Exponential Backoff
     */
    retry_exponential_backoff?: number | null;
    /**
     * Priority Weight
     */
    priority_weight?: number | null;
    /**
     * Weight Rule
     */
    weight_rule?: 'downstream' | 'upstream' | 'absolute' | null;
    /**
     * Task Display Name
     */
    task_display_name?: string | null;
    /**
     * Executor
     */
    executor?: string | null;
    /**
     * Executor Config
     */
    executor_config?: {
        [key: string]: unknown;
    } | null;
    /**
     * Max Active Tis Per Dagrun
     */
    max_active_tis_per_dagrun?: number | null;
    /**
     * Depends On Past
     */
    depends_on_past?: boolean | null;
    /**
     * Disabled
     *
     * Excluded from the generated DAG (kept on the canvas).
     */
    disabled?: boolean;
    /**
     * Lineage
     *
     * OpenLineage selective enable/disable for this task.
     */
    lineage?: 'inherit' | 'enabled' | 'disabled';
    /**
     * Operator template (blueprint) this task was created from; validation enforces the template's locked fields. Not part of the generated DAG.
     */
    template_ref?: TemplateRef | null;
    /**
     * Kind
     */
    kind: 'python_task';
    /**
     * Decorator
     */
    decorator?: 'task' | 'branch' | 'short_circuit' | 'virtualenv' | 'external_python' | 'branch_virtualenv' | 'branch_external_python' | 'sensor' | 'bash' | 'docker' | 'kubernetes' | 'stub' | 'llm' | 'agent' | 'llm_branch' | 'llm_sql';
    /**
     * Decorator Kwargs
     */
    decorator_kwargs?: {
        [key: string]: unknown;
    };
    /**
     * Function Name
     */
    function_name: string;
    /**
     * Arguments
     *
     * Keyword arguments; values may be XCom references.
     */
    arguments?: {
        [key: string]: unknown;
    };
    /**
     * Extra Parameters
     *
     * Additional function parameters without a bound value (e.g. keys provided by expand_kwargs).
     */
    extra_parameters?: Array<string>;
    /**
     * Code
     *
     * Function body (statements). Use `return` to push XCom.
     */
    code: string;
    /**
     * Multiple Outputs
     */
    multiple_outputs?: boolean;
    /**
     * Is Result
     *
     * Airflow >= 3.3: mark as the DAG result (`@result`), returned by the dagRuns/{id}/wait API.
     */
    is_result?: boolean;
    /**
     * Uses Loop Context
     *
     * Inside a loop group: receive the `loop` context (index, previous, result, max_iterations) as a keyword-only parameter.
     */
    uses_loop_context?: boolean;
};

