/**
 * GitStorageSettings
 */
export type GitStorageSettingsWritable = {
    /**
     * Provider
     *
     * Git host API: local (git CLI, any remote), github, gitlab, bitbucket, azure, gitea (Gitea/Forgejo: git CLI push + pull requests over the REST API).
     */
    provider?: 'local' | 'github' | 'gitlab' | 'bitbucket' | 'azure' | 'gitea';
    /**
     * Repo
     *
     * owner/name (github), project id or path (gitlab), workspace/repo (bitbucket), organization/project/repository (azure), remote URL (local, gitea).
     */
    repo?: string | null;
    /**
     * Username
     *
     * Bitbucket app-password user (omit for access tokens).
     */
    username?: string | null;
    /**
     * Azure Bearer
     *
     * Azure DevOps: token is an Entra ID bearer token, not a PAT.
     */
    azure_bearer?: boolean;
    /**
     * Base Branch
     *
     * Defaults to the bundle ref/main.
     */
    base_branch?: string | null;
    /**
     * Subdir
     *
     * Folder inside the repository.
     */
    subdir?: string | null;
    /**
     * Mode
     *
     * pr: a branch + pull request per DAG; push: commit straight to the branch.
     */
    mode?: 'pr' | 'push';
    /**
     * Branch Prefix
     *
     * Prefix of pending-change branches (mode=pr).
     */
    branch_prefix?: string;
    /**
     * Token
     *
     * Personal/project access token, app password or PAT.
     */
    token?: string | null;
    /**
     * Api Url
     *
     * REST API base URL (GitHub Enterprise, self-hosted GitLab, Azure DevOps Server…); default: the public host's. gitea: default <scheme>://<host>/api/v1 of an http(s) repo URL (required for SSH remotes).
     */
    api_url?: string | null;
    /**
     * Environments
     *
     * Environment name -> branch, e.g. {'prod': 'main'}.
     */
    environments?: {
        [key: string]: string;
    };
    /**
     * Use Airflow Bundle
     *
     * Fill repo/branch/subdir/credentials from Airflow's GitDagBundle config.
     */
    use_airflow_bundle?: boolean;
    /**
     * Bundle Name
     *
     * GitDagBundle to read (use_airflow_bundle; default: the first).
     */
    bundle_name?: string | null;
    /**
     * Conn Id
     *
     * Airflow git connection id.
     */
    conn_id?: string | null;
    /**
     * Credentials Ttl
     *
     * Seconds the credentials read from an Airflow connection (conn_id, forced_conn_id, the bundle's or a user's own) are reused before the connection is read again; on an authentication failure it is re-read at once and the operation retried, so a rotated token works without a restart. 0 = read on every operation.
     */
    credentials_ttl?: number;
    /**
     * Cache Dir
     *
     * Clone cache (provider=local).
     */
    cache_dir?: string | null;
    /**
     * Ssh Key File
     *
     * provider=local: SSH key.
     */
    ssh_key_file?: string | null;
    /**
     * Github App Id
     *
     * GitHub App id.
     */
    github_app_id?: string | null;
    /**
     * Github Installation Id
     *
     * GitHub App installation id.
     */
    github_installation_id?: string | null;
    /**
     * Github Private Key
     *
     * GitHub App private key (PEM).
     */
    github_private_key?: string | null;
    /**
     * Github Private Key File
     *
     * GitHub App private key file (PEM).
     */
    github_private_key_file?: string | null;
    /**
     * Fetch Interval
     *
     * provider=local: seconds between fetches of the remote.
     */
    fetch_interval?: number;
    /**
     * Direct Push Roles
     *
     * AutoAir roles allowed to push straight to the target branch (deploy request flag direct_push=true in mode=pr; see iam.force_pr_without_direct_push for mode=push). Evaluated by autoair.iam; unset = iam.direct_push_roles applies (default ['Admin']); [] = nobody, except users granted 'deploy:direct_push' explicitly.
     */
    direct_push_roles?: Array<string> | null;
    /**
     * Forced Conn Id
     *
     * Admin policy: the Airflow connection every git deploy uses. Overrides conn_id (and the bundle's connection); the deploy-target dialog cannot change it.
     */
    forced_conn_id?: string | null;
    /**
     * Credentials Mode
     *
     * shared: one service connection/token for everybody; per_user: commits and pull requests use the deploying user's own Airflow connection (see user_conn_id_template), read with the user's token so Airflow's RBAC applies. Reads (listing, history) keep the shared credentials when configured.
     */
    credentials_mode?: 'shared' | 'per_user';
    /**
     * User Conn Id Template
     *
     * per_user: the user's connection id. Placeholders: {username} (the Airflow username, lower-cased; characters outside [A-Za-z0-9_.-] become '_').
     */
    user_conn_id_template?: string;
    /**
     * User Conn Id Pattern
     *
     * per_user: regex (fullmatch) of connection ids a user may pick in the deploy dialog instead of the template's (e.g. 'git_.*'); unset: only the template.
     */
    user_conn_id_pattern?: string | null;
    /**
     * User Credentials Fallback
     *
     * per_user: use the shared credentials when the user has no readable connection (otherwise such deploys are refused).
     */
    user_credentials_fallback?: boolean;
    /**
     * Request Token
     *
     * Git token the user types for one deploy, delete, promotion or pull request (header X-AutoAir-Git-Token, never stored, logged or audited): off = the header is refused; optional = a token, when given, replaces the configured credentials for that one write; required = every git write needs one (the configured connection, if any, only serves reads; MCP git writes need mcp_request_token and the header). A team target uses its own team_storage.<team>.git.request_token, but off here turns request tokens off for every target. With forced_conn_id set, tokens are refused unless request_token_overrides_forced.
     */
    request_token?: 'off' | 'optional' | 'required';
    /**
     * Request Token Overrides Forced
     *
     * A request token may replace the admin-forced connection (forced_conn_id) for that one write. Default: the forced connection always wins and the X-AutoAir-Git-Token header is refused.
     */
    request_token_overrides_forced?: boolean;
    /**
     * Mcp Request Token
     *
     * MCP over HTTP: save_dag_spec / delete_dag_spec take the user's git token from the X-AutoAir-Git-Token header of the MCP request (set in the MCP client's server configuration; never a tool argument, so it stays out of the model's context and transcripts). request_token, the forced-connection rule and the HTTPS rule apply as for the REST API. Off: such a header is refused.
     */
    mcp_request_token?: boolean;
    /**
     * Request Token Allow Insecure
     *
     * Accept X-AutoAir-Git-Token over plain HTTP from a non-loopback client (the scheme and client address honour server.proxy_headers / forwarded_allow_ips), and send it to http:// git hosts. Only for test setups.
     */
    request_token_allow_insecure?: boolean;
    /**
     * Commit Author
     *
     * Commit author: service = the service identity (the user is credited in trailers and Co-authored-by); user = the deploying user ('Name <email>'); auto = user with per_user credentials, else service. GitHub's API always commits as the token's owner (the user is credited with Co-authored-by).
     */
    commit_author?: 'auto' | 'service' | 'user';
    /**
     * Branch Template
     *
     * mode=pr: branch of a DAG's pending change. Placeholders: {branch_prefix}, {dag_id}, {environment} (may be empty), {environment_path} ('<env>/' or '').
     */
    branch_template?: string;
    /**
     * Promote Branch Template
     *
     * Branch of an environment promotion. Placeholders: {branch_prefix}, {dag_id}, {from_env}, {to_env}.
     */
    promote_branch_template?: string;
    /**
     * Commit Message Template
     *
     * Commit message of a save without a user message. Placeholders: {dag_id}, {environment}, {author} and the context placeholders ({user}, {user_name}, {user_email}, {autoair_version}, {etag_before}, {etag_after}, {validation}, {approvals}, {link}, {target}, {description}, {context}). The context block and trailers are always appended unless the template places {context} itself.
     */
    commit_message_template?: string;
    /**
     * Delete Message Template
     *
     * Commit message (and PR title) of a delete. Placeholders: {dag_id}, {environment}, {author} and the context placeholders (see commit_message_template).
     */
    delete_message_template?: string;
    /**
     * Promote Message Template
     *
     * Commit message (and PR title) of a promotion. Placeholders: {dag_id}, {from_env}, {to_env}, {author} and the context placeholders.
     */
    promote_message_template?: string;
    /**
     * Pr Title Template
     *
     * Pull request title of a save. Placeholders: {dag_id}, {environment}, {author}, {message} (first line of the commit message) and the context placeholders.
     */
    pr_title_template?: string;
    /**
     * Pr Body Template
     *
     * Pull request description. Placeholders: {message} (the commit message without the context), {description} (the PR description typed in the deploy dialog), {dag_id}, {environment}, {author} and the context placeholders. The context block is appended unless the template places {context}; it cannot be removed.
     */
    pr_body_template?: string;
    /**
     * Pr Labels
     *
     * Labels put on opened pull requests (GitHub, GitLab, Azure DevOps, Gitea).
     */
    pr_labels?: Array<string>;
    /**
     * Pr Reviewers
     *
     * Reviewers requested on opened pull requests: GitHub logins (or 'org/team' for teams), GitLab usernames, Bitbucket account UUIDs, Azure DevOps identity ids, Gitea usernames.
     */
    pr_reviewers?: Array<string>;
    /**
     * Pr Draft
     *
     * Open pull requests as drafts.
     */
    pr_draft?: boolean;
    /**
     * Delete Branch After Merge
     *
     * Ask the host to delete the source branch when the pull request is merged (GitLab, Bitbucket, Azure DevOps; on GitHub this is a repository setting).
     */
    delete_branch_after_merge?: boolean;
    /**
     * Committer Name
     *
     * provider=local: committer name of AutoAir commits.
     */
    committer_name?: string;
    /**
     * Committer Email
     *
     * provider=local: committer e-mail (also the author when none is known).
     */
    committer_email?: string;
    /**
     * Timeout
     *
     * Seconds per request to the git host's REST API.
     */
    timeout?: number;
    /**
     * Command Timeout
     *
     * provider=local: seconds a git command may take.
     */
    command_timeout?: number;
    /**
     * Max Attempts
     *
     * Saves retried when the branch moves between read and commit.
     */
    max_attempts?: number;
    /**
     * Read Cache Size
     *
     * File reads at immutable commits kept in memory.
     */
    read_cache_size?: number;
};

/**
 * StorageSettings
 */
export type StorageSettingsWritable = {
    /**
     * Mode
     *
     * Deploy target: a local folder, object storage (fsspec) or a git repository.
     */
    mode?: 'local' | 'object' | 'git';
    /**
     * Allowed Targets
     *
     * Target kinds the deploy-target dialog/API offers and accepts, e.g. ['git'] (only repositories) or ['local'] (only the DAG folder). Admin policy: the UI cannot change it.
     */
    allowed_targets?: Array<'local' | 'object' | 'git'>;
    /**
     * Local Path
     *
     * mode=local: folder written to (default: dags_folder/subfolder).
     */
    local_path?: string | null;
    /**
     * Object Url
     *
     * mode=object: fsspec URL of the bundle prefix.
     */
    object_url?: string | null;
    /**
     * Storage Options
     *
     * mode=object: fsspec storage options (credentials, endpoint…).
     */
    storage_options?: {
        [key: string]: unknown;
    };
    /**
     * History Limit
     *
     * Saved versions kept per DAG.
     */
    history_limit?: number;
    /**
     * File Mode
     *
     * mode=local: permissions (octal) of written files.
     */
    file_mode?: string;
    /**
     * Dir Mode
     *
     * mode=local: permissions (octal) of created folders (default: umask).
     */
    dir_mode?: string | null;
    /**
     * Temp Dir
     *
     * mode=local: folder for the temporary file of atomic writes (default: the target folder). Must be on the same file system, or writes stop being atomic.
     */
    temp_dir?: string | null;
    git?: GitStorageSettingsWritable;
};

